{{ config(
    materialized = 'table', 
    transient=false
) }}

SELECT 
    DATEKEY AS DATE_KEY,
    DayOfWeek AS DAY_OF_WEEK,
    DayOfMonth AS DAY_OF_MONTH,
    DayOfYear AS DAY_OF_YEAR,
    MONTHNAME AS MONTH_NAME,
    MONTHOFYEAR AS MONTH_OF_YEAR,
    CALENDARYEAR AS CALENDAR_YEAR,
    CALENDARYEARMONTH AS CALENDAR_YEAR_MONTH,
    CALENDARYEARQTR AS CALENDAR_YEAR_QUARTER,
    FIRSTDAYOFMONTH AS FIRST_DAY_OF_MONTH,
    LASTDAYOFMONTH AS LAST_DAY_OF_MONTH,
    FIRSTDAYOFQUARTER AS FIRST_DAY_OF_QUARTER,
    LASTDAYOFQUARTER AS LAST_DAY_OF_QUARTER,
    CONCAT(MONTHNAME, ' ', CALENDARYEAR) AS MONTH_NAME_CALENDAR_YEAR
FROM {{ source('eli_dv_bv', 'ref_rt_ref_calendar') }}